#!/usr/bin/env bash
# tests/mathffp_probe.sh - builds tests/mathffp_probe.s (CLI executable, case table generated by
# tests/mathffp_check.py), writes it with a startup-sequence that runs it on a bootable OFS disk, boots the disk in
# an Amiberry session, reads the probe's output buffer through gdb (its bounds are printed on the serial port before
# "MFP fin") into <out_dir>/mathffp.txt and checks it with tests/mathffp_check.py (one PASS/FAIL line per check).
# Expected values: docs/analysis/mathffp-v34.md §7.
#
# Usage: tests/mathffp_probe.sh <out_dir> [rom=build/kick13-prod.rom]
# The Commodore ROM is refused by amiberry-session unless MFP_ANALYSIS=1 (analysis agent only, see CLAUDE.md).
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="${1:?out_dir}"; ROM="${2:-$ROOT/build/kick13-prod.rom}"
A="$ROOT/.claude/skills/amiberry/scripts/amiberry-session"
mkdir -p "$OUT"
python3 -I "$ROOT/tests/mathffp_check.py" gen "$OUT/mathffp_cases.i" || exit 2
vasmm68k_mot -Fhunkexe -kick1hunks -nosym -m68000 -quiet -I "$OUT" -o "$OUT/mathffp_probe" \
  "$ROOT/tests/mathffp_probe.s" || exit 2
printf 'df0:mathffp_probe\n' > "$OUT/startup"
ADF="$OUT/mathffp_$$.adf"; rm -f "$ADF"
xdftool "$ADF" create + format Probe ofs + boot install + makedir s + write "$OUT/startup" s/startup-sequence \
  + write "$OUT/mathffp_probe" mathffp_probe >/dev/null || { echo "xdftool failed"; exit 2; }
NAME="${MFP_NAME:-mfp$$}"
EXTRA=(); DIR="$ROOT/build/amiberry/sessions/$NAME"
[ "${MFP_ANALYSIS:-0}" = 1 ] && { EXTRA=(--analysis); DIR="$ROOT/build/amiberry/analysis/$NAME"; }
"$A" start --name "$NAME" --rom "$ROM" --adf "$ADF" --timeout 120 "${EXTRA[@]}" || exit 2
"$A" wait-serial "$NAME" "MFP fin" 600; RC=$?
if [ $RC = 0 ]; then
  BUF=$(tr -d '\r' < "$DIR/serial.log" | grep -a -m1 -o 'MFP buf=[0-9A-F]\{8\} end=[0-9A-F]\{8\}$')
  S=${BUF#MFP buf=}; S=${S%% *}; E=${BUF##*end=}
  [ -n "$BUF" ] && "$A" gdb "$NAME" -ex "dump binary memory $OUT/mathffp.bin 0x$S 0x$E" >/dev/null
  tr -d '\r' < "$OUT/mathffp.bin" | sed -n '/^MFP debut/,/^MFP fin/p' > "$OUT/mathffp.txt"
fi
"$A" stop "$NAME" >/dev/null
[ $RC = 0 ] || { echo "no MFP fin (timeout)"; exit 1; }
[ -s "$OUT/mathffp.txt" ] || { echo "output buffer not read"; exit 1; }
python3 -I "$ROOT/tests/mathffp_check.py" check "$OUT/mathffp.txt" > "$OUT/mathffp_check.txt"; RC=$?
grep -v '^PASS' "$OUT/mathffp_check.txt"
exit $RC
